  "account.genTitle": "Generiraj kod za Garmin",
  "account.genHelp": "Samo Garmin: ako radije ne želiš očitati kod sa sata, ovdje ga generiraj i upiši u aplikaciji Garmin Connect pod „Pumpfoil“ → Postavke. Wear OS, Apple Watch i Amazfit nemaju taj put — ondje sat prikazuje kod, a ti ga upisuješ gore.",
