  "account.browseAll": "Listaj i ostale zaslone tijekom pauze ili kad ne voziš",
  "account.browseAllHint": "Uključeno (zadano): svaka stranica ostaje dostupna u svakom stanju. Isključeno: samo zasloni koji su ovdje dodijeljeni pojedinom stanju — preglednije, ali na vodi nije sve dostupno.",
