  "account.viewsTitle": "Prikazi aplikacije na satu",
  "account.viewsDesc": "Proizvoljan broj prikaza s do 3 polja. Prebacuj tipkama GORE/DOLJE na satu. (Aplikacija učitava postavke pri pokretanju.)",
  "account.viewsKlassikHint": "Ovi satovi ne mogu prikazati tvoje vlastite rasporede: {names}. Umjesto rasporeda prikazuju njegove prve tri vrijednosti odozgo prema dolje, svaku s nazivom polja. Klasične stranice prikazuju se točno kako si ih postavio.",
  "account.viewsLiteHint": "Ovi satovi imaju vrlo malo memorije: {names}. Tvoje vlastite rasporede prikazuju kao njihove prve tri vrijednosti. Između vožnji i tijekom pauze prikazuju samo prvu stranicu i uvijek listaju kroz sve stranice.",
  "account.colorByValue": "Oboji vrijednosti prema razini (brzina/puls)",
  "account.autoStart": "Automatski pokreni snimanje kad poletim (GPS)",
  "account.stopMode": "Završavanje snimke na satu",
  "account.stopModeHold": "Drži tipku 2 sekunde (zadano)",
  "account.stopModePress": "Dovoljan je jedan pritisak",
  "account.stopModeHint": "Vrijedi za sve tvoje satove. Držanje je zadano, pa slučajan pritisak tijekom vožnje ništa ne završava. „Jedan pritisak“ je za one koji su na to navikli ili čiji sat već koristi dugi pritisak za nešto drugo (na nekim Garminima to je „čovjek u moru“). Držanje i dalje radi, pa dobivaš drugi način, a ne gubiš nijedan. Za odbacivanje sat tada jednom pita.",
  "account.recordMode": "Način snimanja",
  "account.recordModeFull": "Puni · 25 Hz",
  "account.recordModeLite": "Lite · 10 Hz",
  "account.smallBuffer": "Ovaj sat ima vrlo malo prostora za snimke. Garmin ne dopušta prijenos podataka tijekom aktivnosti, a od početka 2026. Garmin više ne otvara svoje izravno sučelje za podatke novim projektima — pa naša aplikacija mora sve pohraniti na samom satu. Na ovom satu taj je prostor pun nakon otprilike 30–40 minuta, a sve snimljeno nakon toga se gubi. Za duže sesije: završi snimku nakon 30–40 minuta, pričekaj prijenos i pokreni novu. Dijelove možeš poslije spojiti („Usporedi i spoji“).",
  "account.recordModeGps": "Samo GPS",
  "account.gnssMode": "Satelitski sustavi",
  "account.gnssModeBest": "Svi (najbolja pokrivenost)",
  "account.gnssModeL1": "Bez drugog frekvencijskog pojasa",
  "account.gnssModeTwo": "GPS + jedan sustav",
  "account.gnssModeGps": "Samo GPS (najštedljivije)",
  "account.gnssModeHint": "Više sustava brže i pouzdanije pronalazi tvoj položaj, ali troši više baterije. Samo Garmin, od verzije sata 1.0.77.",
  "account.standardPage": "Zadana stranica iz zajednice: „{name}“, autor {author}",
  "account.gpsSparen": "Uštedi prostor: snimaj samo oko vožnji",
  "account.gpsSparenHint": "Sat pohranjuje GPS i podatke o kretanju samo dok si brži od 6 km/h, plus 30 sekundi prije i poslije. Plivanje, čekanje i povratak pješice se ne pohranjuju. Vožnje, pumpovi i vrijeme na foilu ostaju praktički isti (provjereno na 141 sesiji: vrijeme na foilu −0,15 %, pumpovi −0,3 %); na karti nedostaje samo put između vožnji.",
  "account.gpsSparenUhr": "Ovaj sat: izmjereni prostor oko {kb} KB. Pri {modus} to traje oko {ohne} minuta bez uštede, a uz uštedu obično {von}–{bis} minuta – ovisno o tome koliko vremena provedeš sporije od 6 km/h.",
  "account.gpsSparenUhrUnbekannt": "Za ovaj sat još nije izmjereno ograničenje prostora – to obično znači da ima dovoljno mjesta. Ušteda ne škodi, ali ovdje malo donosi.",
  "account.gpsSparenNotfall": "Ako tijekom snimanja ponestaje prostora (manje od 100 KB slobodno), sat sam uključuje uštedu i od tada pohranjuje samo GPS. Snimka se nastavlja i vožnje se i dalje prepoznaju, ali od tog trenutka bez pumpova.",
  "account.gpsSparenAus": "Isključi ako ti treba potpuni trag na karti. Vrijedi od verzije sata 1.0.92.",
  "account.fitAccel": "Podaci o kretanju u Garmin aktivnosti",
  "account.fitAccelAuto": "Automatski (trenutno: {jetzt})",
  "account.fitAccelJetztAn": "uključeno",
  "account.fitAccelJetztAus": "isključeno",
  "account.fitAccelOn": "Uključeno",
  "account.fitAccelOff": "Isključeno",
  "account.fitAccelHint": "Upisuje li sat podatke o kretanju i u Garminovu vlastitu datoteku aktivnosti (ono što stiže u Garmin Connect). Neovisno o gornjem načinu snimanja, koji određuje što ide u naš prijenos. Isključi ako se tvoj sat zamrzne ili ponovno pokrene nakon sesije.",
  "account.fitAccelNirgends": "Uz „Samo GPS“ gore i ovo isključeno, podaci o kretanju nigdje se ne snimaju — pumpovi će nedostajati.",
  "account.fitAccelUpdate": "Tvoja aplikacija na satu prestara je za ovu postavku — ažuriraj Pumpfoil aplikaciju na satu (verzija 1.0.100 ili novija).",
  "account.sparModusFull": "25 Hz s podacima o kretanju",
  "account.sparModusLite": "10 Hz s podacima o kretanju",
  "account.sparModusGps": "samo GPS",
  "account.waterLock": "Zaključavanje za vodu",
  "account.waterLockAuto": "Automatski (preporučeno)",
  "account.waterLockOn": "Uvijek uključeno",
  "account.waterLockOff": "Isključeno",
  "account.waterLockHint": "Tijekom pumpanja voda na zaslonu pokreće radnje. Zaključavanje onemogućuje dodir dok ne pritisneš tipku. \"Automatski\" znači da sat sam odlučuje — samo tamo gdje se ne možeš zaključati vani. Garminu to nije potrebno.",
  "account.accelWakeup": "Drži senzor kretanja budnim (test)",
  "account.accelWakeupDefault": "Zadano ({v})",
  "account.accelWakeupOn": "Uključeno",
  "account.accelWakeupOff": "Isključeno",
  "account.accelWakeupHint": "Neki Wear OS satovi gube podatke o kretanju kad tijekom snimanja zadrijemaju – tada nedostaju pumpovi. \"Uključeno\" ih vraća, ali može trošiti više baterije. Još se testira: isprobaj i vrati natrag ako baterija pati. Od verzije sata 1.2.33.",
  "account.recordModeGpsHint": "Broj pumpova, učestalost i faze klizanja nedostaju u ovom načinu — računaju se iz senzora kretanja.",
  "account.recordModeHint": "Ako se snimanje prekida na satu s malo memorije (npr. Forerunner 55), odaberi „Lite“ ili „Samo GPS“. Samo GPS daje udaljenost/brzinu/faze na foilu, ali bez prepoznavanja pumpova.",
  "account.recordModeMoved": "Brzina snimanja sada se postavlja za svaki sat, uz tvoje povezane satove.",
  "account.recordModeAutoLite": "Ovaj sat je automatski ograničen s „Puni“ na „Lite“ (ograničena memorija).",
  "account.recordModeGarminHint": "Kao koja vrsta aktivnosti se tvoja snimka pojavljuje u Garmin Connectu, postavljaš u profilu pod „Vrsta aktivnosti u Garmin Connectu“.",
  "account.devicesSettingsIntro": "Postavke ispod svakog sata djeluju na sam sat. Preuzima ih sljedeći put kad tamo otvoriš aplikaciju — ažuriranje nije potrebno.",
  "account.claimNextTitle": "Što sada možeš postaviti za ovaj sat",
  "account.claimNextGarmin": "Na popisu satova ispod možeš za ovaj sat odabrati dvije stvari: način snimanja (25 Hz, 10 Hz ili samo GPS) i satelitske sustave. Oboje određuje koliko baterije troši. Ako ti je trajanje baterije važno: „Bez drugog frekvencijskog pojasa“ štedi najviše bez štete za analizu, a 10 Hz košta tvoj broj pumpova manje od pola posto. Ne biraj samo GPS — tada potpuno nestaju broj pumpova, učestalost i faze klizanja.",
  "account.claimNextRecord": "Na popisu satova ispod možeš odabrati način snimanja za ovaj sat (25 Hz, 10 Hz ili samo GPS). 10 Hz štedi bateriju i košta tvoj broj pumpova manje od pola posto. Ne biraj samo GPS — tada potpuno nestaju broj pumpova, učestalost i faze klizanja.",
  "account.claimNextZepp": "Tvoj Amazfit sada odavde preuzima jezik, prikaz pauze i vlastite rasporede. Način snimanja s popisa satova još ne preuzima — snima vlastitom brzinom.",
