  "sd.gpsWarning": "⚠️ U ovoj datoteci nema podataka o ubrzanju — prepoznavanje foila radi samo grubo putem GPS-a (brzina). Faze pumpanja/klizanja nedostaju; granice vožnji i prepoznavanje mogu biti netočni (previše ili premalo prepoznato).",
  "sd.gpsFrozen": "Tijekom ove snimke tvoj sat nikad nije dao vlastiti položaj — stalno je ponavljao isti pohranjeni položaj, pa nema udaljenosti, brzine ni vožnji. Obično pomaže ostaviti mobitel dalje od vode (ili isključiti Bluetooth na satu) kako bi sat koristio vlastiti GPS.",
