  "sd.tapDeleteAll": "Izbriši pokušaje",
  "sd.tapDeleteConfirm": "Izbrisati svih {n} spremljenih pokušaja za ovaj krug?",
  "sd.tapHelp": "<b>Označavanje pumpova</b> — označi stvarne pumpove za treniranje automatskog prepoznavanja. Treba ti <b>video</b> sesije.<br><br><b>Kako:</b><br>1. Odaberi <b>krug</b> gore.<br>2. <b>Usklađivanje:</b> pronađi jasan <b>GPS lom</b> vidljiv i na tragu i na videu (npr. oštar zavoj). Klikni <b>Start (3-2-1)</b> i pokreni video tako da oboje teku zajedno na tom lomu.<br>3. Pritisni <b>razmaknicu</b> na <b>svaki</b> pump (ili <b>PUMP</b>). Zatim <b>Spremi pokušaj</b>.<br>4. Označi isti krug <b>3–4×</b>, zatim <b>Usporedi</b>.<br><br><b>Što je važno:</b><br>• Usklađivanje <b>ne</b> mora biti točno — ±½ takta pumpanja (~0,3–0,5 s) je u redu; 1 s je granično, nekoliko sekundi previše (pumpovi su periodični, inače postaje dvosmisleno). Koristi <b>isti lom</b> u svim pokušajima.<br>• Važnije od apsolutne točnosti je <b>ujednačeno</b> dodirivanje onoga što vidiš — više pokušaja automatski poništava tvoje kašnjenje reakcije.<br>• Bodovanje počinje <b>od prvog dodira</b>; zalet prije se ne računa. Slučajni dodiri (npr. pljusak kad padneš) izbacuju se <b>većinom</b> pokušaja.<br>• Označavaj <b>samo pumpove</b> — faze klizanja slijede automatski (sve između pumpova). Ne označavaj ništa dodatno.",
  "sd.tapSaveTake": "Spremi pokušaj",
