  "watches.legYes": "potpuno podržano",
  "watches.legPartial": "ograničeno",
  "watches.legNo": "nije dostupno",
  "watches.foot": "Pumpovi i faze klizanja trebaju sirovo ubrzanje (≥25 Hz) izravno sa sata. GPS statistika može se analizirati uvozom FIT datoteka/podataka za mnoge marke.",
  "watches.nGarmin": "Stariji modeli bez sirovog ubrzanja: GPS statistika se i dalje analizira.",
  "watches.nApple": "Sirovo ubrzanje putem Core Motiona.",
  "watches.nWear": "Radi na svakom Wear OS 3+ satu — Samsung Galaxy Watch, Google Pixel Watch, TicWatch/Mobvoi, Fossil, OnePlus.",
  "watches.nAmazfit": "Pristup senzorima ovisi o modelu.",
  "watches.nHuawei": "U izradi: snima na satu, prenosi putem Pumpfoil aplikacije na Android mobitelu. Koje podatke satovi daju, još treba testirati.",
  "watches.nHuaweiW5": "Nakon povezivanja kodom prenosi samostalno, aplikacija na mobitelu nije potrebna. Novo u AppGalleryju.",
  "watches.nGarminConnect": "Poveži račun → aktivnosti stižu automatski. Snimljeno našom aplikacijom za sat: puno prepoznavanje pumpova. Ostale Garmin aktivnosti: ovisno o tome što snimaju — GPS i puls, možda i pumpovi.",
  "watches.nPolar": "Poveži račun → uvoz treninga (GPS + puls). API izvoz ne uključuje tok sirovog ubrzanja visoke frekvencije potreban za prepoznavanje pumpova (samo putem zasebnog BLE senzora).",
  "watches.nSuunto": "Poveži račun → uvoz treninga (GPS + puls). FIT izvoz (još) ne uključuje tok sirovog ubrzanja visoke frekvencije potreban za prepoznavanje pumpova.",
  "linked.xiaomi.title": "Xiaomi i Redmi satovi",
  "linked.xiaomi.hint": "Nema izravne veze s Xiaomijem — ali postoji službeni zaobilazni put: Mi Fitness šalje tvoje treninge u Suunto aplikaciju, a mi ih preuzimamo odande. Za to ti treba (besplatni) Suunto račun.",
  "linked.xiaomi.step1": "U Mi Fitnessu: iPhone → Profil → Povezane aplikacije → autoriziraj Suunto. Android → Profil → Postavke → Podaci trećih strana → Suunto.",
  "linked.xiaomi.step2": "Zatim dodirni „Poveži“ na Suunto kartici gore i koristi isti Suunto račun.",
  "linked.xiaomi.step3": "Idi voziti. Tvoje sesije nakon toga stižu ovamo automatski.",
  "linked.xiaomi.note": "Xiaomi nudi ovu vezu u cijelom svijetu osim u Kini. Aplikacija na samom satu nije moguća — Xiaomi ne dopušta aplikacije trećih strana.",
  "land.connectXiaomi": "putem Mi Fitness + Suunto",
  "watches.nXiaomi": "Nema aplikacije na satu (Xiaomi ne dopušta aplikacije trećih strana). Ali Mi Fitness službeno šalje tvoje treninge u Suunto aplikaciju — poveži Suunto i stižu ovamo. Upute pod „Povezani računi“.",
  "watches.linkViaSuunto": "putem Mi Fitness → Suunto",
  "watches.nFitbit": "Aplikacije trećih strana su ukinute.",
  "import.title": "Uvezi aktivnost",
  "import.short": "Uvezi",
  "import.intro": "Učitaj snimljenu aktivnost za analizu — FIT, TCX ili GPX, i kao ZIP, pa i starije sesije.",
