  "cls.notPumpfoil": "Ne izgleda kao pumpfoil",
  "cls.confirmFlag": "Misliš da ovo nije pumpfoil sesija? Vlasnik će dobiti ljubaznu molbu da je ispravno razvrsta — na primjer kao wingfoil ili foildrive. Ostaješ anoniman i nikoga se ni za što ne optužuje: radi se samo o tome da rekordi ostanu usporedivi.",
  "cls.thanks": "Hvala! Vlasnik će biti zamoljen da razvrsta ovu sesiju.",
  "cls.fileAsk": "Tvoj sat je spremio ovu snimku kao „{sport}“, pa ne možemo znati je li to bilo pumpanje. Hoćeš li je razvrstati? Do tada se neće pojaviti ni u jednoj statistici. Ako je ipak bilo pumpanje, samo odaberi „Pumpfoil“.",
  "cls.ownerAsk": "Drugi foiler misli da ova sesija nije pumpanje. Možeš li je razvrstati? Do tada se neće pojaviti ni u jednoj statistici. Ako je stvarno bilo pumpanje, samo nam javi pa ćemo pogledati.",
