  "cls.autoAsk": "Ova sesija nam ne izgleda kao pumpanje — zato se zasad ne računa ni u jednoj statistici. Možeš li je razvrstati? Ako je stvarno bilo pumpanje, samo odaberi „Pumpfoil“.",
