  "team.event.teilnehmer1": "Sudionik",
  "team.event.ohneDateienKurz": "Računaju se samo snimke sa sata, iz aplikacije ili s povezanog računa, bez prenesenih datoteka.",
  "team.eventbild.titel": "Banner događaja",
