  "team.vorlage.gpskunst": "GPS umjetnost: tko nacrta najkul sliku na vodi?",
  "kunst.einstellungHinweis": "Umjesto ljestvica: vozači predaju jednu sliku po rundi iz jedne svoje sesije, zatim zajednica anonimno glasa srcima. Sljedeća runda u međuvremenu već traje.",
  "kunst.rundenTage": "Nova runda svakih (dana)",
  "kunst.abstimmenTage": "Glasanje nakon toga (dana)",
  "kunst.regeln": "Svaka runda broji samo tvoje sesije snimljene tijekom te runde, bilo koji sport, i na kopnu.\nCrta se samo tvoje vrijeme na foilu. Više vožnji može se spojiti, ali samo uzastopne iz iste sesije.\nSvatko predaje jednu sliku po rundi i može je mijenjati ili povući do kraja runde.\nSlike drugih postaju vidljive tek kad počne glasanje.\nNakon runde slijedi glasanje: anonimno, prikazuje se samo linija, svatko ima 3 srca i nijedno za vlastitu sliku.\nTko je dobio koliko srca otkriva se tek nakon glasanja — tada s imenom i spotom (osim ako je skriven).\nHumor je dobrodošao. Uklanja se samo stvarno zabranjen sadržaj; vozač vidi razlog.",
  "kunst.test.titel": "Testni način (samo administratori)",
  "kunst.test.hinweis": "broje se tvoje sesije iz zadnjih 60 dana, a faza svake runde ovdje se može postaviti ručno. Isključi to za pravi događaj.",
