  "brett.erkl.titel": "Što je položaj daske?",
  "brett.erkl.was": "Ako je tvoj mobitel tijekom sesije pričvršćen na dasku, njegov žiroskop mjeri kako se daska naginje naprijed-natrag i bočno – izravno na izvoru umjesto na zapešću.",
  "brett.erkl.wie": "Kako to radi: stavi mobitel u vodootpornu futrolu, pričvrsti ga ravno na palubu i pokreni snimanje u Pumpfoil aplikaciji na mobitelu. Tvoj sat može snimati istovremeno. Analiza obično sama primijeti da je mobitel bio na dasci.",
  "brett.erkl.bringt": "Što dobivaš: vidiš koliko je tvoja daska stabilna tijekom pumpanja, koliko se naginje naprijed-natrag i bočno po pumpu te razlikuje li se to između foilova, zavoja i ravnih dionica. Svaka takva snimka pomaže i poboljšati prepoznavanje pumpova za sat.",
  "brett.erkl.daten": "Podaci koje dobivaš: nagib i bočno naginjanje po pumpu, nagnutost, učestalost pumpanja, zavoji naspram ravnih dionica i hub (kretanje gore-dolje, kad je ritam pumpanja pouzdano prepoznat) – po vožnji, a ovdje kao pregled svih vožnji i po foilu.",
  "brett.erkl.mehr": "Saznaj više",
