  "why.title": "Zašto pumpfoil.org?",
  "why.intro": "Vožnje i pumpove mogu brojati i drugi. pumpfoil.org radi više:",
  "why.k1t": "Zajednica, ne samo statistika",
  "why.k1": "Ljestvice po spotu, vremenskom okviru i veličini foila, timovi s vlastitim ljestvicama i događajima, stranice spotova s opisima, toplinskim kartama i rutama od ljudi koji ondje voze, prijatelji i tko upravo gdje pumpa, chat, videozapisi i rasporedi sata za dijeljenje. Ne pumpaš samo za sebe – vidiš što se događa na tvom spotu i diljem svijeta.",
  "why.k2t": "Izradio ga je netko tko i sam vozi",
  "why.k2": "Jan je počeo u lipnju 2026. jer ono što je htio nije postojalo – i otad gradi gotovo svaki dan.",
  "why.k3t": "Zajednica ima pravo glasa",
  "why.k3": "Ideje iz chata i gumba za povratne informacije često se nađu na stranici u roku od nekoliko dana; svi koji pomognu dobivaju malu značku podržavatelja. Ne pišeš službi za podršku, nego izravno osobi koja ga gradi.",
  "why.k4t": "Slobodni softver",
  "why.k4": "Cijeli kod je otvoren na GitHubu (AGPL). Svatko može provjeriti što se događa s njegovim podacima, pomoći u izradi ili ga nastaviti – projekt ne ovisi o tvrtki koja bi ga sutra mogla ugasiti ili prodati.",
  "why.k5t": "Tvoji podaci pripadaju tebi",
  "why.k5": "Bez praćenja, bez kolačića, bez oglasa, bez prodaje podataka. Sve se može preuzeti kao GPX, FIT ili CSV, a tvoj račun sa svime u njemu nestaje pritiskom na gumb.",
  "why.k6t": "Transparentnost",
  "why.k6": "Otvoreno govorimo što radi, a što (još) ne: koliko je prepoznavanje pumpova i klizanja zaista točno i na čemu se temelji, koji sat što može, koja je verzija u trgovini odbijena i zašto, što su otkrili naši sigurnosni pregledi. Popis promjena svaki dan pokazuje što je novo i koliko je daleko analiza za svaki sport – bez marketinških obećanja, samo stvarno stanje.",
  "why.k7t": "Što se više ljudi pridruži, to bolje za sve",
  "why.k7": "Svaka sesija, svaka ocjena analize, svaka snimka s mobitelom na dasci pomaže da prepoznavanje bude točnije – i od toga imaju koristi svi koji voze. A sve analize otvorene su svima u zajednici, uključujući ukupnu statistiku po foilu i po satu: koji foil leti koliko daleko, koji sat koliko dobro snima? Svatko doprinosi svojim vožnjama, a svaki vozač čini ljestvice, spotove i rute živahnijima.",
  "why.k8t": "Za svaki sat, ne za jednu marku",
  "why.k8": "Garmin, Apple Watch, Wear OS, Amazfit, plus Polar, Suunto, COROS i tvoj mobitel – ne moraš kupiti određeni sat da bi se pridružio. Naše vlastite aplikacije za Huawei i Suunto upravo su u pregledu trgovine i stižu što prije.",
  "why.k9t": "Besplatno, na 18 jezika",
  "why.k9": "Uključujući švicarski njemački i austrijski njemački.",
  "why.outro": "Isprobaj i reci nam što nedostaje – možda to vidiš već sljedeći tjedan. Have fun, keep pumping!",
  "nav.why": "Zašto pumpfoil.org?",
